const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade.","sections":[{"h":"What is a share?","p":"A share (or stock) is a small piece of ownership in a company. If a company has 1,00,000 shares and you hold 100, you own 0.1% of it. Your return comes mainly from price changes and, sometimes, dividends.","ul":["If the company grows, shareholders may benefit.","If the price falls, you can lose money.","Listed companies trade on stock exchanges."]},{"h":"Exchanges, indices and brokers","p":"In India, the main exchanges are NSE and BSE. You buy and sell through a SEBI-registered broker, using a demat account (which holds shares electronically) and a trading account.","ul":["NIFTY 50 tracks 50 large companies listed on NSE.","SENSEX tracks 30 large companies listed on BSE.","The broker passes your order on; the exchange matches buyers with sellers."]},{"h":"Order types and settlement","p":"A market order buys or sells immediately at the best available price. A limit order sets the maximum you will pay or the minimum you will accept. Equity trades settle on T+1, meaning the next trading day, in India.","ul":["Check your broker's rules and charges before placing orders.","Prices can move between placing and executing an order.","Have funds or shares ready before the settlement date."]}]},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs."},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks."},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators."},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal."},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies."},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।","sections":[{"h":"शेयर क्या है?","p":"शेयर (स्टॉक) किसी कंपनी में मालिकाना हक का एक छोटा हिस्सा है। अगर किसी कंपनी के 1,00,000 शेयर हैं और आपके पास 100 शेयर हैं, तो आपके पास उसका 0.1% हिस्सा है। आपका लाभ या नुकसान मुख्य रूप से कीमत बदलने से होता है, और कभी-कभी डिविडेंड से भी।","ul":["कंपनी बढ़ती है तो शेयरधारकों को लाभ हो सकता है।","कीमत गिरे तो पैसा डूब भी सकता है।","लिस्टेड कंपनियों के शेयर स्टॉक एक्सचेंज पर ट्रेड होते हैं।"]},{"h":"एक्सचेंज, इंडेक्स और ब्रोकर","p":"भारत में मुख्य एक्सचेंज NSE और BSE हैं। आप SEBI-पंजीकृत ब्रोकर के ज़रिए डीमैट खाते (जिसमें शेयर इलेक्ट्रॉनिक रूप में रहते हैं) और ट्रेडिंग खाते से ख़रीद-बिक्री करते हैं।","ul":["NIFTY 50, NSE की 50 बड़ी कंपनियों को दर्शाता है।","SENSEX, BSE की 30 बड़ी कंपनियों को दर्शाता है।","ब्रोकर आपका ऑर्डर आगे भेजता है; एक्सचेंज ख़रीदार और विक्रेता का मिलान करता है।"]},{"h":"ऑर्डर के प्रकार और सेटलमेंट","p":"मार्केट ऑर्डर उपलब्ध सबसे अच्छी कीमत पर तुरंत ख़रीदता या बेचता है। लिमिट ऑर्डर आपकी अधिकतम खरीद या न्यूनतम बिक्री कीमत तय करता है। भारत में इक्विटी ट्रेड का सेटलमेंट T+1 होता है, यानी अगले ट्रेडिंग दिन।","ul":["ऑर्डर देने से पहले अपने ब्रोकर के नियम और शुल्क जाँचें।","ऑर्डर देने और पूरा होने के बीच कीमत बदल सकती है।","सेटलमेंट की तारीख़ से पहले ज़रूरी फ़ंड या शेयर तैयार रखें।"]}]},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।"},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।"},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।"},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।"},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।"},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"foundations":{"sections":[{"h":"1. What the stock market is","p":"A stock market is a marketplace where companies sell small pieces of ownership, called shares, and where people then buy and sell those shares with each other. It does two jobs. It helps companies raise money to grow, and it lets owners sell when they need cash. Because owners can sell, people are willing to buy shares in the first place.","ul":["Primary market: a company sells new shares for the first time, for example through an IPO (initial public offering). The company receives the money.","Secondary market: investors trade shares among themselves on an exchange. This is where almost all daily trading happens. The money moves from one investor to another, not to the company.","A listed company is one whose shares are traded on a recognised exchange, such as NSE or BSE."]},{"h":"2. What a share is and how you earn from it","p":"Owning one share makes you a part-owner of that company, however small your stake. Your money can grow in two ways, and it can also shrink. Nothing is guaranteed.","ul":["Capital gain: you sell for more than you paid. Example: you buy 10 shares at ₹500 (₹5,000) and sell at ₹550 (₹5,500). The gain is ₹500 before costs and tax.","Dividend: a share of profit the company pays to shareholders, usually per share. Example: ₹10 per share on 10 shares gives ₹100. Dividends are decided by the company and are not guaranteed.","Capital loss: if the price falls, your holding loses value. Example: you sell the same 10 shares at ₹420 and lose ₹800 before costs.","Limited liability: as a shareholder you can lose the money you invested, but you are not responsible for the company's debts beyond that amount."]},{"h":"3. Who is who in the market","p":"Several parties work together for a trade to happen and for your shares to be safe.","ul":["You (the investor): decide what to buy and sell, and bear the gains and losses.","Broker: a SEBI-registered firm that takes your orders and sends them to the exchange.","Stock exchanges (NSE and BSE): run the trading system where buyers and sellers are matched.","Clearing corporations: guarantee that trades settle, by taking the risk that one side does not pay or deliver.","Depositories (NSDL and CDSL): hold your shares electronically in your demat account.","SEBI (Securities and Exchange Board of India): the regulator that sets rules, licenses intermediaries and protects investors.","Asset management companies (AMCs): run mutual funds, which pool money from many investors."]},{"h":"4. Open the accounts you need","p":"To invest in shares you need three things: a bank account, a demat account and a trading account. Many brokers open the demat and trading accounts together.","ul":["KYC (Know Your Customer): proof of identity and address, usually PAN and Aadhaar, a bank account, a photograph and a signature. It can often be done online.","Demat account: holds your shares in electronic form. You do not receive paper share certificates for shares held this way.","Trading account: lets you place buy and sell orders through your broker. Your money for trades sits here.","Nomination: name a nominee so your holdings can pass to them safely if something happens to you.","Choose a SEBI-registered broker. Check their registration on SEBI's website before you open an account, and be wary of anyone who promises returns."]},{"h":"5. Market timings and trading sessions","p":"Indian equity markets trade on working days, and the timings below are typical. Check the exact times and the holiday list on the NSE or BSE website each year, because they can change.","ul":["Pre-open session (around 9:00 to 9:08 for orders, then price discovery until 9:15): orders are collected and an opening price is set.","Normal trading session (around 9:15 to 15:30): continuous buying and selling. This is when most trades happen.","Closing session after 15:30: used to settle the closing price for certain orders. Check current timings on the exchange website.","Exchange holidays: the market is closed on published holidays, so no trades happen on those days.","Orders placed outside market hours are usually held until the next session. Some brokers offer after-market orders (AMO) that are sent when the market opens."]},{"h":"6. Order types, explained","p":"An order is your instruction to the exchange. The type you choose controls how sure you are of the price and whether the trade will happen.","ul":["Market order: buy or sell now at the best available price. The trade is very likely to happen, but the price can move before it fills.","Limit order: you set the price. Example: buy only at ₹495 or lower. You control the price, but the order may never fill if the price does not reach your limit.","Stop-loss (SL) order: a limit order that becomes active when the price reaches a trigger. Example: trigger ₹240 with limit ₹239 for a sell means: when the price falls to ₹240, try to sell at ₹239 or better.","Stop-loss market (SL-M): becomes a market order at the trigger price. It is more likely to fill, but the price may be worse than the trigger.","Validity: a Day order lasts for the session. An IOC (immediate or cancel) order fills right away or is cancelled."]},{"h":"7. Product types: delivery and intraday","p":"Your broker will ask which product you want for each order. The choice must match your plan, because the rules and risks are different.","ul":["Delivery (usually called CNC): you buy and hold the shares in your demat account for as long as you want. You pay the full price. This is how most long-term investors invest.","Intraday (usually called MIS): you buy and sell within the same day. You must close the position by a cut-off time, and brokers may square it off automatically. It uses margin (borrowed money) and can cause large losses.","Never use intraday or margin products without understanding them. Start with delivery trades while you learn."]},{"h":"8. Settlement: when shares and money actually move","p":"A trade does not change ownership on the spot. Settlement is the process that moves the shares and the money. In India, equity trades settle on T+1, which means one trading day after the trade.","ul":["Example: on Monday at 10:00 you buy 10 shares. The order is executed on Monday and you receive a contract note.","On Tuesday (T+1), the shares are credited to your demat account and the money is debited from your trading account, if the settlement goes through.","After you sell, the sale money is usually available to withdraw after settlement. Check your broker's rules on when it becomes available."]},{"h":"9. What trading costs you","p":"Every trade has costs that come out of your return. Charges vary by broker and change over time, so read your broker's charge page and your contract note.","ul":["Brokerage: the broker's fee for executing the trade.","Exchange transaction charges and SEBI turnover fee: charged by the exchange and the regulator.","Stamp duty: charged on the buying side.","STT (Securities Transaction Tax): a government tax on the transaction, with rates that depend on the type of trade.","GST: charged on brokerage and some other charges.","Depository charges: charged when you sell shares from your demat account."],"p2":"Illustration: you buy ₹5,000 of shares and sell at ₹5,500, with ₹60 of total costs. Your net gain is ₹440, not ₹500. Costs matter most for small or frequent trades."},{"h":"10. How prices move","p":"A share price changes when buyers and sellers disagree about its value at the current price. Understanding the basic mechanics helps you read the screen and avoid surprises.","ul":["Order book: shows the current buy orders (bids) and sell orders (asks) at each price. The best bid is the highest buy price; the best ask is the lowest sell price.","Spread: the gap between the best bid and the best ask. A narrow spread usually means a liquid stock.","Volume: the number of shares traded in a period. Higher volume means more participation.","News, company results, economic data and global markets all shift demand and supply, and so move prices.","Circuit limits: an exchange sets a daily upper and lower price band for many stocks. If the price hits a band, trading in that stock may pause or be restricted. Limits can differ by stock."]},{"h":"11. Indices, market size and company categories","ul":["NIFTY 50 (NSE) and SENSEX (BSE) are indices that track large companies. They show the overall direction of the market.","Market capitalisation = share price × total number of shares. SEBI groups listed companies into large, mid and small caps by market-cap rank. Check SEBI's current definition.","Large caps are usually more stable. Small caps can grow faster, but their prices can swing much more.","An index is a benchmark. Compare your returns with it to judge how well you are doing."]},{"h":"12. Taxes on your gains (basics only)","p":"Gains from shares are taxed. Tax rates and rules change with the Union Budget, so always check the current rules with a tax professional or the official income tax website before you file.","ul":["Profits from frequent or intraday trading are usually treated as business income.","Profits from shares held as investments are capital gains. The tax depends on how long you held the shares (short-term or long-term).","Keep your contract notes, P&L statements and bank records. They are needed when you file your return."]},{"h":"13. Protect yourself from scams","p":"Scams target new investors. The warning signs are often easy to spot once you know them.","ul":["No one can guarantee returns from shares. Any promise of fixed high returns is a warning sign.","Be careful with stock tips on WhatsApp or Telegram, and with groups that ask for money to 'join' a trading club.","Check that anyone advising you or managing your money is SEBI-registered, using SEBI's list of registered intermediaries.","Never share your OTP, PIN, or demat and trading login details with anyone.","If you have a complaint, SEBI's SCORES portal is the official way to raise it."]},{"h":"14. Your first-steps checklist","ul":["Set a goal and a time frame, for example saving for a house in seven years.","Build an emergency fund of about 3 to 6 months of expenses before you invest for growth.","Learn in this order: Stock Market Foundations, Investing, SIP and Mutual Funds, Reading Charts, Risk Management. Then move on to the rest.","Start with a small amount that you can afford to lose.","Keep a journal of every decision, including why you made it. Review it monthly, not daily."]}]}},"hi":{"foundations":{"sections":[{"h":"1. शेयर बाज़ार क्या है","p":"शेयर बाज़ार वह बाज़ार है जहाँ कंपनियाँ स्वामित्व के छोटे हिस्से बेचती हैं, जिन्हें शेयर कहते हैं, और फिर लोग इन शेयरों को आपस में ख़रीदते-बेचते हैं। इसके दो काम हैं। यह कंपनियों को बढ़ने के लिए पैसा जुटाने में मदद करता है, और मालिकों को नकद चाहिए तो बेचने की सुविधा देता है। चूँकि मालिक बेच सकते हैं, इसलिए लोग शेयर ख़रीदने को तैयार होते हैं।","ul":["प्राइमरी मार्केट: कंपनी पहली बार नए शेयर बेचती है, जैसे IPO (प्रारंभिक सार्वजनिक निर्गम) के ज़रिए। पैसा कंपनी को मिलता है।","सेकेंडरी मार्केट: निवेशक एक्सचेंज पर आपस में शेयर ट्रेड करते हैं। रोज़ का लगभग सारा ट्रेडिंग यहीं होता है। पैसा एक निवेशक से दूसरे के पास जाता है, कंपनी के पास नहीं।","लिस्टेड कंपनी वह है जिसके शेयर NSE या BSE जैसे मान्यता प्राप्त एक्सचेंज पर ट्रेड होते हैं।"]},{"h":"2. शेयर क्या है और इससे कमाई कैसे होती है","p":"एक शेयर रखने पर आप उस कंपनी के हिस्सेदार बन जाते हैं, चाहे हिस्सा कितना भी छोटा हो। आपका पैसा दो तरीकों से बढ़ सकता है, और घट भी सकता है। कुछ भी गारंटीड नहीं है।","ul":["कैपिटल गेन: आप जितने में ख़रीदते हैं उससे ज़्यादा में बेचते हैं। उदाहरण: 10 शेयर ₹500 पर (₹5,000) ख़रीदे और ₹550 पर (₹5,500) बेचे। शुल्क और टैक्स से पहले लाभ ₹500।","डिविडेंड: कंपनी द्वारा शेयरधारकों को मुनाफ़े का हिस्सा, आमतौर पर प्रति शेयर। उदाहरण: 10 शेयरों पर ₹10 प्रति शेयर = ₹100। डिविडेंड कंपनी तय करती है और यह गारंटीड नहीं है।","कैपिटल लॉस: कीमत गिरे तो आपकी होल्डिंग की वैल्यू घटती है। उदाहरण: वही 10 शेयर ₹420 पर बेचे तो शुल्क से पहले ₹800 का नुकसान।","सीमित दायित्व: शेयरधारक के रूप में आप लगाई गई रकम तक नुकसान उठा सकते हैं, पर कंपनी के कर्ज़ की ज़िम्मेदारी उस रकम से आगे आपकी नहीं होती।"]},{"h":"3. बाज़ार में कौन कौन है","p":"कोई ट्रेड होने और आपके शेयर सुरक्षित रहने के लिए कई पक्ष मिलकर काम करते हैं।","ul":["आप (निवेशक): तय करते हैं कि क्या ख़रीदना और बेचना है, और लाभ-हानि आपकी होती है।","ब्रोकर: SEBI-पंजीकृत फर्म जो आपके ऑर्डर लेकर एक्सचेंज को भेजती है।","स्टॉक एक्सचेंज (NSE और BSE): वह ट्रेडिंग सिस्टम चलाते हैं जिसमें ख़रीदार और विक्रेता का मिलान होता है।","क्लियरिंग कॉर्पोरेशन: गारंटी देते हैं कि ट्रेड सेटल हों, यानी एक पक्ष के भुगतान या डिलीवरी न करने का जोखिम वे उठाते हैं।","डिपॉज़िटरी (NSDL और CDSL): आपके शेयर आपके डीमैट खाते में इलेक्ट्रॉनिक रूप में रखते हैं।","SEBI (भारतीय प्रतिभूति और विनिमय बोर्ड): नियामक जो नियम बनाता है, मध्यस्थों को लाइसेंस देता है और निवेशकों की रक्षा करता है।","एसेट मैनेजमेंट कंपनी (AMC): म्यूचुअल फंड चलाती है, जो कई निवेशकों का पैसा इकट्ठा करते हैं।"]},{"h":"4. ज़रूरी खाते कैसे खोलें","p":"शेयर में निवेश के लिए तीन चीज़ें चाहिए: बैंक खाता, डीमैट खाता और ट्रेडिंग खाता। कई ब्रोकर डीमैट और ट्रेडिंग खाता एक साथ खोल देते हैं।","ul":["KYC (Know Your Customer): पहचान और पते का प्रमाण, आमतौर पर PAN और आधार, बैंक खाता, फ़ोटो और हस्ताक्षर। यह अक्सर ऑनलाइन हो जाता है।","डीमैट खाता: आपके शेयर इलेक्ट्रॉनिक रूप में रखता है। इस तरीके से रखे शेयरों के पेपर सर्टिफ़िकेट नहीं मिलते।","ट्रेडिंग खाता: ब्रोकर के ज़रिए ख़रीद-बिक्री के ऑर्डर देने देता है। ट्रेड के लिए आपका पैसा यहीं रहता है।","नॉमिनेशन: किसी नॉमिनी का नाम दें, ताकि कुछ होने पर आपकी होल्डिंग उन्हें सुरक्षित मिल सके।","SEBI-पंजीकृत ब्रोकर चुनें। खाता खोलने से पहले SEBI की वेबसाइट पर उसका पंजीकरण जाँचें, और रिटर्न का वादा करने वाले किसी भी व्यक्ति से सावधान रहें।"]},{"h":"5. बाज़ार का समय और ट्रेडिंग सत्र","p":"भारतीय इक्विटी बाज़ार कार्यदिवसों पर खुलता है, और नीचे दिए समय सामान्य हैं। हर साल सटीक समय और छुट्टियों की सूची NSE या BSE की वेबसाइट पर जाँचें, क्योंकि ये बदल सकते हैं।","ul":["प्री-ओपन सत्र (लगभग 9:00 से 9:08 तक ऑर्डर, फिर 9:15 तक मूल्य निर्धारण): ऑर्डर इकट्ठे होते हैं और एक शुरुआती कीमत तय होती है।","सामान्य ट्रेडिंग सत्र (लगभग 9:15 से 15:30 तक): लगातार ख़रीद-बिक्री। ज़्यादातर ट्रेड इसी समय होते हैं।","15:30 के बाद क्लोज़िंग सत्र: कुछ ऑर्डरों के लिए क्लोज़िंग कीमत तय करने में उपयोग। मौजूदा समय एक्सचेंज की वेबसाइट पर देखें।","एक्सचेंज की छुट्टियाँ: घोषित छुट्टियों पर बाज़ार बंद रहता है और कोई ट्रेड नहीं होता।","बाज़ार समय के बाहर दिए ऑर्डर आमतौर पर अगले सत्र तक रुकते हैं। कुछ ब्रोकर आफ़्टर-मार्केट ऑर्डर (AMO) देते हैं, जो बाज़ार खुलने पर भेजे जाते हैं।"]},{"h":"6. ऑर्डर के प्रकार, विस्तार से","p":"ऑर्डर एक्सचेंज को दिया गया आपका निर्देश है। जो प्रकार चुनते हैं वह तय करता है कि कीमत पर आप कितने निश्चित हैं और ट्रेड होगा या नहीं।","ul":["मार्केट ऑर्डर: अभी उपलब्ध सबसे अच्छी कीमत पर ख़रीदें या बेचें। ट्रेड होने की संभावना बहुत है, पर भराई से पहले कीमत बदल सकती है।","लिमिट ऑर्डर: कीमत आप तय करते हैं। उदाहरण: केवल ₹495 या उससे कम पर ख़रीदें। कीमत पर आपका नियंत्रण है, पर कीमत आपकी लिमिट तक न पहुँचे तो ऑर्डर पूरा नहीं होगा।","स्टॉप-लॉस (SL) ऑर्डर: एक लिमिट ऑर्डर जो ट्रिगर कीमत पहुँचने पर सक्रिय होता है। उदाहरण: बिक्री के लिए ट्रिगर ₹240 और लिमिट ₹239, यानी कीमत ₹240 तक गिरे तो ₹239 या उससे बेहतर पर बेचने की कोशिश।","स्टॉप-लॉस मार्केट (SL-M): ट्रिगर कीमत पर मार्केट ऑर्डर बन जाता है। पूरा होने की संभावना ज़्यादा है, पर कीमत ट्रिगर से बदतर हो सकती है।","वैधता: डे ऑर्डर उस सत्र तक चलता है। IOC (तुरंत या रद्द) ऑर्डर अभी भरता है या रद्द हो जाता है।"]},{"h":"7. प्रोडक्ट के प्रकार: डिलीवरी और इंट्राडे","p":"आपका ब्रोकर हर ऑर्डर के लिए प्रोडक्ट पूछेगा। चुनाव आपकी योजना से मेल खाना चाहिए, क्योंकि नियम और जोखिम अलग हैं।","ul":["डिलीवरी (आमतौर पर CNC): आप शेयर ख़रीदकर डीमैट खाते में जितने समय तक चाहें रखते हैं। पूरी कीमत चुकानी होती है। ज़्यादातर दीर्घकालिक निवेशक इसी तरह निवेश करते हैं।","इंट्राडे (आमतौर पर MIS): एक ही दिन में ख़रीदना और बेचना। पोज़िशन एक तय समय तक बंद करनी होती है, और ब्रोकर इसे अपने आप बंद (स्क्वेयर ऑफ़) कर सकता है। इसमें मार्जिन (उधार का पैसा) लगता है और बड़ा नुकसान हो सकता है।","जब तक समझ न हो, इंट्राडे या मार्जिन प्रोडक्ट न छुएँ। सीखते समय डिलीवरी ट्रेड से शुरू करें।"]},{"h":"8. सेटलमेंट: शेयर और पैसा असल में कब चलते हैं","p":"ट्रेड होते ही मालिकाना हक नहीं बदलता। सेटलमेंट वह प्रक्रिया है जिसमें शेयर और पैसा चलते हैं। भारत में इक्विटी ट्रेड T+1 पर सेटल होते हैं, यानी ट्रेड के एक ट्रेडिंग दिन बाद।","ul":["उदाहरण: सोमवार सुबह 10:00 बजे आपने 10 शेयर ख़रीदे। ऑर्डर सोमवार को पूरा हुआ और आपको कॉन्ट्रैक्ट नोट मिला।","मंगलवार (T+1) को, सेटलमेंट सफल हो तो शेयर आपके डीमैट खाते में आते हैं और पैसा ट्रेडिंग खाते से कटता है।","बेचने के बाद बिक्री की रकम आमतौर पर सेटलमेंट के बाद निकालने योग्य होती है। कब उपलब्ध होगी, यह अपने ब्रोकर के नियम में जाँचें।"]},{"h":"9. ट्रेडिंग में खर्च क्या हैं","p":"हर ट्रेड के कुछ खर्च होते हैं जो आपके रिटर्न से कटते हैं। खर्च ब्रोकर के अनुसार अलग होते हैं और समय के साथ बदलते हैं, इसलिए ब्रोकर का चार्ज पेज और कॉन्ट्रैक्ट नोट ज़रूर पढ़ें।","ul":["ब्रोकरेज: ट्रेड करने के लिए ब्रोकर की फ़ीस।","एक्सचेंज ट्रांज़ैक्शन चार्ज और SEBI टर्नओवर फ़ीस: एक्सचेंज और नियामक द्वारा लिए जाते हैं।","स्टाम्प ड्यूटी: ख़रीद की तरफ़ लगती है।","STT (सिक्योरिटीज़ ट्रांज़ैक्शन टैक्स): लेनदेन पर सरकारी टैक्स, दर ट्रेड के प्रकार पर निर्भर।","GST: ब्रोकरेज और कुछ अन्य चार्ज पर लगता है।","डिपॉज़िटरी चार्ज: डीमैट खाते से शेयर बेचने पर लगता है।"],"p2":"उदाहरण: आप ₹5,000 के शेयर ख़रीदते हैं और ₹5,500 पर बेचते हैं, कुल खर्च ₹60। शुद्ध लाभ ₹440 है, ₹500 नहीं। छोटे या बार-बार होने वाले ट्रेड में खर्च सबसे ज़्यादा मायने रखते हैं।"},{"h":"10. कीमतें कैसे बदलती हैं","p":"शेयर की कीमत तब बदलती है जब ख़रीदार और विक्रेता मौजूदा कीमत पर उसकी वैल्यू को लेकर असहमत होते हैं। बुनियादी तंत्र समझने से स्क्रीन पढ़ना और अचानक होने वाली बातों से बचना आसान होता है।","ul":["ऑर्डर बुक: हर कीमत पर मौजूदा ख़रीद ऑर्डर (बिड) और बिक्री ऑर्डर (आस्क) दिखाती है। सबसे ऊँची बिड सबसे ऊँची ख़रीद कीमत है; सबसे कम आस्क सबसे कम बिक्री कीमत।","स्प्रेड: सबसे अच्छी बिड और सबसे अच्छे आस्क के बीच का अंतर। कम स्प्रेड आमतौर पर लिक्विड शेयर को दर्शाता है।","वॉल्यूम: किसी अवधि में ट्रेड हुए शेयर। ज़्यादा वॉल्यूम का मतलब ज़्यादा भागीदारी।","ख़बरें, कंपनी के नतीजे, आर्थिक आँकड़े और वैश्विक बाज़ार, सभी माँग और आपूर्ति बदलते हैं और इसलिए कीमतें भी।","सर्किट लिमिट: एक्सचेंज कई शेयरों के लिए एक दिन की ऊपरी और निचली कीमत सीमा तय करता है। कीमत सीमा छूए तो उस शेयर में ट्रेडिंग रुक सकती है या सीमित हो सकती है। सीमाएँ शेयर के अनुसार अलग हो सकती हैं।"]},{"h":"11. इंडेक्स, बाज़ार का आकार और कंपनी की श्रेणियाँ","ul":["NIFTY 50 (NSE) और SENSEX (BSE) बड़ी कंपनियों को दर्शाने वाले इंडेक्स हैं। ये बाज़ार की कुल दिशा दिखाते हैं।","मार्केट कैपिटलाइज़ेशन = शेयर कीमत × कुल शेयरों की संख्या। SEBI मार्केट-कैप रैंक के आधार पर लिस्टेड कंपनियों को लार्ज, मिड और स्मॉल कैप में बाँटता है। SEBI की मौजूदा परिभाषा जाँचें।","लार्ज कैप आमतौर पर ज़्यादा स्थिर होते हैं। स्मॉल कैप तेज़ी से बढ़ सकते हैं, पर उनकी कीमतें बहुत ज़्यादा ऊपर-नीचे हो सकती हैं।","इंडेक्स एक बेंचमार्क है। अपने रिटर्न की तुलना इससे करें ताकि पता चले कि आप कैसा कर रहे हैं।"]},{"h":"12. लाभ पर टैक्स (केवल मूल बातें)","p":"शेयर से होने वाले लाभ पर टैक्स लगता है। टैक्स दरें और नियम केंद्रीय बजट के साथ बदलते हैं, इसलिए रिटर्न भरने से पहले मौजूदा नियम किसी टैक्स विशेषज्ञ या आयकर विभाग की आधिकारिक वेबसाइट से जाँचें।","ul":["बार-बार या इंट्राडे ट्रेडिंग से होने वाले लाभ आमतौर पर बिज़नेस इनकम माने जाते हैं।","निवेश के रूप में रखे शेयरों से लाभ कैपिटल गेन होते हैं। टैक्स इस पर निर्भर करता है कि शेयर कितने समय तक रखे (अल्पकालिक या दीर्घकालिक)।","कॉन्ट्रैक्ट नोट, P&L स्टेटमेंट और बैंक रिकॉर्ड सँभालकर रखें। रिटर्न भरते समय इनकी ज़रूरत होती है।"]},{"h":"13. घोटालों से ख़ुद को बचाएँ","p":"घोटाले नए निवेशकों को निशाना बनाते हैं। एक बार पता हो जाए तो चेतावनी के संकेत अक्सर साफ़ दिखते हैं।","ul":["कोई भी शेयर से निश्चित ऊँचे रिटर्न की गारंटी नहीं दे सकता। ऐसा वादा ही सबसे बड़ी चेतावनी है।","WhatsApp या Telegram पर शेयर टिप्स से सावधान रहें, और ऐसे समूहों से भी जो 'ट्रेडिंग क्लब' में शामिल होने के लिए पैसे माँगते हैं।","जो भी व्यक्ति आपको सलाह दे या आपका पैसा संभाले, उसका SEBI-पंजीकरण SEBI की पंजीकृत मध्यस्थों की सूची से जाँचें।","अपना OTP, PIN या डीमैट और ट्रेडिंग लॉगिन किसी के साथ न बाँटें।","शिकायत हो तो SEBI का SCORES पोर्टल आधिकारिक तरीका है।"]},{"h":"14. आपकी पहली शुरुआत की चेकलिस्ट","ul":["लक्ष्य और समय-सीमा तय करें, जैसे सात साल में घर के लिए बचत।","ग्रोथ के लिए निवेश से पहले लगभग 3 से 6 महीने के खर्च जितना इमरजेंसी फ़ंड बनाएँ।","इस क्रम में सीखें: स्टॉक मार्केट फ़ाउंडेशन, निवेश, SIP और म्यूचुअल फंड, चार्ट पढ़ना, रिस्क मैनेजमेंट। फिर बाक़ी मॉड्यूल पर जाएँ।","कम रकम से शुरू करें, जितना खोने की आप क्षमता रखते हों।","हर फ़ैसले का जर्नल रखें, जिसमें यह भी लिखें कि फ़ैसला क्यों लिया। हर महीने समीक्षा करें, रोज़ नहीं।"]}]}}};
const LESSON_EXTRAS_EN = {"foundations":{"examples":[{"title":"Buying 10 shares","text":"A stock trades at ₹500. Buying 10 shares costs 10 × ₹500 = ₹5,000 (plus brokerage and taxes). If the price rises to ₹550, the holding is worth ₹5,500, a gain of ₹500, or 10% before costs."},{"title":"Limit order that never fills","text":"The stock is at ₹500 and you place a limit buy at ₹495. If the price never drops to ₹495, your order stays open and you do not own the shares. A limit order protects the price but does not guarantee a trade."}],"scenarios":[{"title":"Placing an order before the opening bell","text":"You place a market buy at 9:20 am, before the open. News overnight has moved the stock, so the price opens 4% higher than yesterday's close. Your order fills at the new price. A limit order would have capped what you pay."},{"title":"Planning when cash becomes available","text":"You sell shares on Monday. Under T+1 the sale settles on Tuesday. If you need the money on Monday, the cash is not yet yours to withdraw. Check your broker's rules on when sale proceeds become available."}],"useCases":["Checking company announcements on NSE or BSE before you buy, since listed companies must disclose material news.","Using NIFTY 50 as a benchmark: if your portfolio gained 6% while the index gained 9%, you trailed the market.","Understanding why your shares sit in a demat account and how a sale moves them out."],"takeaways":["A share is a fraction of ownership; your return depends on price and dividends.","A market order gets filled quickly at an uncertain price; a limit order controls the price but may not fill.","Know your settlement cycle (T+1) before you plan to use sale money.","Always check brokerage and taxes, because they reduce the real return."],"practice":[{"q":"A company has 2 crore shares. How many shares is 0.5% of the company?","a":"0.5% × 2,00,00,000 = 1,00,000 shares."},{"q":"Which order is more likely to be executed right away: market or limit?","a":"A market order, although the final price is uncertain. A limit order guarantees the price, not the execution."},{"q":"You buy shares on Monday under T+1. On which day does the purchase settle?","a":"Tuesday, the next trading day."}]}};
const LESSON_EXTRAS_HI = {"foundations":{"examples":[{"title":"10 शेयर ख़रीदना","text":"एक शेयर ₹500 पर ट्रेड करता है। 10 शेयर ख़रीदने की लागत 10 × ₹500 = ₹5,000 है (ब्रोकरेज और टैक्स अलग से)। अगर कीमत ₹550 हो जाए, तो होल्डिंग ₹5,500 की होगी, यानी शुल्क से पहले ₹500 का लाभ या 10%।"},{"title":"लिमिट ऑर्डर जो कभी पूरा नहीं होता","text":"शेयर ₹500 पर है और आप ₹495 पर लिमिट ख़रीद ऑर्डर लगाते हैं। अगर कीमत कभी ₹495 तक नहीं आती, तो ऑर्डर खुला रहता है और आपके पास शेयर नहीं आते। लिमिट ऑर्डर कीमत की सुरक्षा देता है, पर ट्रेड की गारंटी नहीं।"}],"scenarios":[{"title":"सुबह की घंटी से पहले ऑर्डर लगाना","text":"आप सुबह 9:20 बजे, ओपनिंग से पहले, मार्केट ऑर्डर लगाते हैं। रात की ख़बर से शेयर कल के क्लोज़ से 4% ऊपर खुलता है, और आपका ऑर्डर नई कीमत पर पूरा होता है। लिमिट ऑर्डर आपके भुगतान की ऊपरी सीमा तय कर देता।"},{"title":"पैसा कब मिलेगा, यह योजना बनाना","text":"आप सोमवार को शेयर बेचते हैं। T+1 के तहत बिक्री का सेटलमेंट मंगलवार को होगा। अगर पैसा सोमवार को चाहिए, तो वह अभी निकालने योग्य नहीं है। अपने ब्रोकर से पूछें कि बिक्री की रकम कब उपलब्ध होती है।"}],"useCases":["ख़रीदने से पहले NSE या BSE पर कंपनी की घोषणाएँ देखना, क्योंकि लिस्टेड कंपनियों को महत्वपूर्ण ख़बरें बतानी होती हैं।","NIFTY 50 को बेंचमार्क बनाना: अगर आपका पोर्टफ़ोलियो 6% बढ़ा और इंडेक्स 9%, तो आप बाज़ार से पीछे रहे।","समझना कि शेयर डीमैट खाते में क्यों रहते हैं और बिक्री पर वे कैसे बाहर जाते हैं।"],"takeaways":["शेयर स्वामित्व का एक हिस्सा है; आपका रिटर्न कीमत और डिविडेंड पर निर्भर करता है।","मार्केट ऑर्डर जल्दी पूरा होता है पर कीमत अनिश्चित रहती है; लिमिट ऑर्डर कीमत तय करता है पर पूरा नहीं भी हो सकता।","पैसा इस्तेमाल करने की योजना से पहले अपना सेटलमेंट चक्र (T+1) जानें।","टैक्स और ब्रोकरेज हमेशा देखें, क्योंकि ये असली रिटर्न घटाते हैं।"],"practice":[{"q":"किसी कंपनी के 2 करोड़ शेयर हैं। 0.5% हिस्सा कितने शेयर का है?","a":"0.5% × 2,00,00,000 = 1,00,000 शेयर।"},{"q":"कौन सा ऑर्डर तुरंत पूरा होने की ज़्यादा संभावना रखता है: मार्केट या लिमिट?","a":"मार्केट ऑर्डर, हालाँकि अंतिम कीमत अनिश्चित होती है। लिमिट ऑर्डर कीमत की गारंटी देता है, पूरा होने की नहीं।"},{"q":"आपने सोमवार को T+1 के तहत शेयर ख़रीदे। ख़रीद किस दिन सेटल होगी?","a":"मंगलवार, अगले ट्रेडिंग दिन।"}]}};
const LESSON_CHARTS = {"foundations":[{"file":"trade-lifecycle.svg","en":{"alt":"Flow: you, broker, exchange, clearing corporation, depository; trade day T and settlement on T+1","cap":"What happens after you press Buy: the exchange matches the order on trade day (T) and shares reach your demat on the next trading day (T+1)."},"hi":{"alt":"प्रवाह: आप, ब्रोकर, एक्सचेंज, क्लियरिंग कॉरपोरेशन, डिपॉज़िटरी; ट्रेड दिन T और T+1 पर सेटलमेंट","cap":"Buy दबाने के बाद क्या होता है: एक्सचेंज ट्रेड के दिन (T) ऑर्डर मिलाता है और अगले ट्रेडिंग दिन (T+1) शेयर आपके डीमैट में आते हैं।"}}]};
