const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Share (stock)","hi":"शेयर (स्टॉक)"},"def":{"en":"A unit of ownership in a company. Holding shares makes you a part-owner.","hi":"किसी कंपनी में स्वामित्व की एक इकाई। शेयर रखने पर आप उस कंपनी के हिस्सेदार होते हैं।"}},{"cat":"basics","term":{"en":"Equity","hi":"इक्विटी"},"def":{"en":"Ownership in a company through shares. Also used for the value left for shareholders after debts.","hi":"शेयरों के ज़रिए कंपनी में स्वामित्व। कर्ज़ चुकाने के बाद शेयरधारकों के हिस्से की राशि को भी इक्विटी कहते हैं।"}},{"cat":"basics","term":{"en":"Index","hi":"इंडेक्स"},"def":{"en":"A measure that tracks a selected group of shares, such as NIFTY 50 or SENSEX.","hi":"चुनी हुई कंपनियों के समूह की कीमत को मापने वाला पैमाना, जैसे NIFTY 50 या SENSEX।"}},{"cat":"india","term":{"en":"NIFTY 50","hi":"NIFTY 50"},"def":{"en":"An index of 50 large companies listed on the National Stock Exchange (NSE).","hi":"NSE पर सूचीबद्ध 50 बड़ी कंपनियों का इंडेक्स।"}},{"cat":"india","term":{"en":"SENSEX","hi":"SENSEX"},"def":{"en":"An index of 30 large companies listed on the Bombay Stock Exchange (BSE).","hi":"BSE पर सूचीबद्ध 30 बड़ी कंपनियों का इंडेक्स।"}},{"cat":"india","term":{"en":"NSE and BSE","hi":"NSE और BSE"},"def":{"en":"India's two main stock exchanges, where listed shares are bought and sold.","hi":"भारत के दो मुख्य स्टॉक एक्सचेंज, जहाँ सूचीबद्ध शेयर ख़रीदे और बेचे जाते हैं।"}},{"cat":"india","term":{"en":"SEBI","hi":"SEBI"},"def":{"en":"The Securities and Exchange Board of India, the regulator that protects investors and oversees markets.","hi":"भारतीय प्रतिभूति और विनिमय बोर्ड, जो निवेशकों की रक्षा करता है और बाज़ार की निगरानी करता है।"}},{"cat":"india","term":{"en":"Demat account","hi":"डीमैट खाता"},"def":{"en":"An account that holds your shares in electronic form.","hi":"वह खाता जिसमें आपके शेयर इलेक्ट्रॉनिक रूप में रहते हैं।"}},{"cat":"india","term":{"en":"Trading account","hi":"ट्रेडिंग खाता"},"def":{"en":"The account used to place buy and sell orders through a broker.","hi":"ब्रोकर के ज़रिए ख़रीद-बिक्री ऑर्डर देने के लिए इस्तेमाल होने वाला खाता।"}},{"cat":"india","term":{"en":"KYC","hi":"KYC"},"def":{"en":"Know Your Customer: identity and address verification required before you can invest.","hi":"Know Your Customer: निवेश से पहले पहचान और पते की पुष्टि।"}},{"cat":"basics","term":{"en":"Broker","hi":"ब्रोकर"},"def":{"en":"A registered intermediary that executes your buy and sell orders on an exchange.","hi":"एक पंजीकृत मध्यस्थ जो एक्सचेंज पर आपके ख़रीद-बिक्री ऑर्डर पूरे करता है।"}},{"cat":"trading","term":{"en":"Order","hi":"ऑर्डर"},"def":{"en":"An instruction to buy or sell a security at a given price or at the best available price.","hi":"किसी सिक्योरिटी को तय या सबसे अच्छी उपलब्ध कीमत पर ख़रीदने या बेचने का निर्देश।"}},{"cat":"trading","term":{"en":"Market order","hi":"मार्केट ऑर्डर"},"def":{"en":"An order to buy or sell immediately at the best available price. The final price may differ from the displayed one.","hi":"तुरंत सबसे अच्छी उपलब्ध कीमत पर ख़रीदने या बेचने का ऑर्डर। अंतिम कीमत दिखाई गई कीमत से अलग हो सकती है।"}},{"cat":"trading","term":{"en":"Limit order","hi":"लिमिट ऑर्डर"},"def":{"en":"An order to buy at or below, or sell at or above, a set price. It may not execute.","hi":"तय कीमत या उससे कम पर ख़रीदने, या उससे अधिक पर बेचने का ऑर्डर। यह पूरा नहीं भी हो सकता।"}},{"cat":"trading","term":{"en":"Stop-loss order","hi":"स्टॉप-लॉस ऑर्डर"},"def":{"en":"An order that becomes a market or limit order when price reaches a set level, to limit a loss. It is not guaranteed to fill at that level.","hi":"कीमत तय स्तर पर पहुँचने पर बदलने वाला ऑर्डर, जो नुकसान सीमित करता है। उसी स्तर पर पूरा होने की गारंटी नहीं।"}},{"cat":"trading","term":{"en":"Bid and ask","hi":"बिड और आस्क"},"def":{"en":"Bid is the highest price a buyer offers; ask is the lowest price a seller accepts.","hi":"बिड वह सबसे ऊँची कीमत है जो ख़रीदार देता है; आस्क वह सबसे कम कीमत है जिस पर विक्रेता बेचता है।"}},{"cat":"trading","term":{"en":"Spread","hi":"स्प्रेड"},"def":{"en":"The gap between bid and ask. Narrow spreads usually mean a liquid stock.","hi":"बिड और आस्क के बीच का अंतर। कम स्प्रेड आमतौर पर लिक्विड शेयर को दर्शाता है।"}},{"cat":"trading","term":{"en":"Liquidity","hi":"लिक्विडिटी"},"def":{"en":"How easily an asset can be bought or sold without moving its price much.","hi":"कीमत को ज़्यादा प्रभावित किए बिना किसी एसेट को कितनी आसानी से ख़रीदा या बेचा जा सकता है।"}},{"cat":"india","term":{"en":"Settlement (T+1)","hi":"सेटलमेंट (T+1)"},"def":{"en":"The process of transferring shares and money after a trade. In India, equity trades settle one trading day after the trade (T+1).","hi":"ट्रेड के बाद शेयर और पैसे का हस्तांतरण। भारत में इक्विटी ट्रेड अगले ट्रेडिंग दिन (T+1) सेटल होते हैं।"}},{"cat":"india","term":{"en":"Circuit limit","hi":"सर्किट लिमिट"},"def":{"en":"A maximum daily upper or lower price move allowed for a stock. Trading may pause when it is hit.","hi":"किसी शेयर की एक दिन में अधिकतम ऊपरी या निचली कीमत सीमा। इसके छूने पर ट्रेडिंग रुक सकती है।"}},{"cat":"basics","term":{"en":"Volume","hi":"वॉल्यूम"},"def":{"en":"The number of shares traded in a period. High volume means more participation.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। ज़्यादा वॉल्यूम का मतलब ज़्यादा भागीदारी।"}},{"cat":"basics","term":{"en":"Market capitalisation (market cap)","hi":"मार्केट कैप"},"def":{"en":"Share price multiplied by the number of shares outstanding. Companies are grouped as large, mid or small cap.","hi":"शेयर कीमत को बकाया शेयरों की संख्या से गुणा करने पर मिलने वाली कंपनी की कुल वैल्यू। कंपनियाँ लार्ज, मिड या स्मॉल कैप में बाँटी जाती हैं।"}},{"cat":"basics","term":{"en":"Dividend","hi":"डिविडेंड (लाभांश)"},"def":{"en":"A share of profit a company pays to its shareholders, usually per share.","hi":"कंपनी द्वारा शेयरधारकों को दिया जाने वाला मुनाफ़े का हिस्सा, आमतौर पर प्रति शेयर।"}},{"cat":"trading","term":{"en":"Intraday","hi":"इंट्राडे"},"def":{"en":"Trades opened and closed within the same trading session. Positions must be squared off before the market closes.","hi":"एक ही ट्रेडिंग सत्र में खुले और बंद होने वाले ट्रेड। बाज़ार बंद होने से पहले पोज़िशन बंद करनी होती है।"}},{"cat":"trading","term":{"en":"Brokerage","hi":"ब्रोकरेज"},"def":{"en":"The fee a broker charges for executing a trade.","hi":"ट्रेड पूरा करने के लिए ब्रोकर द्वारा लिया जाने वाला शुल्क।"}},{"cat":"india","term":{"en":"STT (Securities Transaction Tax)","hi":"STT (सिक्योरिटीज़ ट्रांज़ैक्शन टैक्स)"},"def":{"en":"A tax charged by the government on securities transactions, varying by trade type.","hi":"प्रतिभूति लेनदेन पर सरकार द्वारा लगाया जाने वाला टैक्स, जो ट्रेड के प्रकार के अनुसार बदलता है।"}}];
